// validators/asset.ts
interface AssetRow {
  inventoryNumber: string;
  name: string;
  mol: string;
  cost: number;
  accountingDate: Date | null;
}

export function validateAssetRow(row: Record<string, any>): { valid: true; data: AssetRow } | { valid: false; error: string } {
  const inventoryNumber = String(row['Инвентарный номер'] || '').trim();
  const name = String(row['Наименование'] || '').trim();
  const mol = String(row['МОЛ'] || '').trim();
  const costStr = String(row['Стоимость'] || '0');

  if (!inventoryNumber || inventoryNumber.length > 50) return { valid: false, error: 'Invalid inventoryNumber' };
  if (!name || name.length > 200) return { valid: false, error: 'Invalid name' };

  const cost = parseFloat(costStr);
  if (isNaN(cost) || cost < 0) return { valid: false, error: 'Invalid cost' };

  let accountingDate: Date | null = null;
  if (row['Дата постановки']) {
    const parsed = new Date(row['Дата постановки']);
    if (isNaN(parsed.getTime()) || parsed > new Date()) {
      return { valid: false, error: 'Invalid accountingDate' };
    }
    accountingDate = parsed;
  }

  return { valid: true, data: { inventoryNumber, name, mol, cost, accountingDate } };
}

