export async function logAuthEvent(userId: string, action: 'register' | 'login', req: any, db: any) {
  const ipAddress = req.ip || req.socket.remoteAddress || 'unknown';
  await db.auditLog.create({
    data: {
      userId,
      action,
      entity: 'user',
      entityId: userId,
      ipAddress,
      userAgent: req.headers['user-agent'] || 'unknown',
      details: action === 'register' ? JSON.stringify({ email: req.body.email }) : null,
    },
  });
}

